{
  "bbb_prediction": "pass",
  "claims": [
    {
      "card_ids": ["C25"],
      "claim": "In mice, 6-MOMIPP brain concentrations mirror plasma concentrations, demonstrating ready BBB penetration in a close 6-methoxy indole analogue of harmine.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C30"],
      "claim": "MOMIPP reaches brain concentrations about 50-60% of plasma in mice for up to 8 hours, providing direct evidence of meaningful CNS exposure in a structurally related methoxy indole.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C12"],
      "claim": "O-methylbufotenine, a 6-methoxy tryptamine, shows brain/blood ratios above 1 in mice over 60 minutes, supporting CNS access for methoxy indole alkaloids.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C01"],
      "claim": "MEAI, a small methoxy indane-like molecule, shows rapid brain influx and a brain-to-plasma ratio of 5.5 in rats, demonstrating that related small methoxy heterocycles can achieve high CNS exposure.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C05"],
      "claim": "6-MeO-THBC penetrates the BBB poorly in mice, but it is the saturated tetrahydro-beta-carboline lacking the aromatic pyridine ring and C1-methyl of harmine, making this contradictory result less transferable.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "high",
  "decision_summary": "Harmine is a 6-methoxy-1-methyl-beta-carboline with high passive BBB plausibility and multiple close methoxy-indole analogues showing direct brain penetration; the one poor-penetration analogue is a saturated tetrahydro-beta-carboline with lower structural transfer. Overall evidence supports meaningful CNS access.",
  "evidence_gaps": [
    "No direct harmine-specific brain/plasma or CSF pharmacokinetic record is present in the supplied evidence.",
    "Efflux transporter status for harmine was not directly measured, though the basic amine raises moderate transporter uncertainty."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

